const body = $input.first().json.body;
const events = body.events;

// Skip verification pings (empty events)
if (!events || events.length === 0) {
  return [];
}

const event = events[0];

// Only handle text messages
if (event.type !== 'message' || event.message.type !== 'text') {
  return [];
}

return [{
  json: {
    text: event.message.text,
    replyToken: event.replyToken,
    userId: event.source.userId
  }
}];

const baseUrl = 'https://raw.githubusercontent.com/sirago23/DEMO_LLM_WIKI/main/wiki/';
const pages = [
  'index.md',
  'concepts/shipping-policy.md',
  'concepts/order-cancellation-policy.md',
  'concepts/damaged-missing-merchandise.md',
  'concepts/refund-policy.md',
  'concepts/return-process.md',
  'concepts/like-new-condition.md',
  'entities/beanz.md',
  'entities/safonia-shipping-protection.md'
];

const results = [];
for (const page of pages) {
  try {
    const content = await this.helpers.httpRequest({ method: 'GET', url: baseUrl + page });
    results.push('=== ' + page + ' ===\n' + content);
  } catch (e) {
    results.push('=== ' + page + ' ===\n[Error: ' + e.message + ']');
  }
}

return [{ json: { wikiContent: results.join('\n\n') } }];
